import pytest
from freebusy import free_slots

WEEK = ("mon", "tue", "wed", "thu", "fri")
WEEKEND = ("sat", "sun")
ALL_DAYS = WEEK + WEEKEND


class TestBasicFunctionality:
    def test_single_attendee_all_free(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_single_attendee_partial_working_hours(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T10:00Z", "2025-06-02T15:00Z", 1)
        assert result == [("2025-06-02T10:00:00Z", "2025-06-02T15:00:00Z")]

    def test_multiple_attendees_simple(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        bob = {"tz": "UTC", "hours": {d: ["10:00-16:00"] for d in WEEK}}
        result = free_slots([alice, bob], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 1)
        assert result == [("2025-06-02T10:00:00Z", "2025-06-02T16:00:00Z")]

    def test_three_attendees_intersection(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-18:00"] for d in WEEK}}
        bob = {"tz": "UTC", "hours": {d: ["10:00-17:00"] for d in WEEK}}
        charlie = {"tz": "UTC", "hours": {d: ["11:00-16:00"] for d in WEEK}}
        result = free_slots([alice, bob, charlie], "2025-06-02T09:00Z", "2025-06-02T18:00Z", 1)
        assert result == [("2025-06-02T11:00:00Z", "2025-06-02T16:00:00Z")]


class TestNoFreeSlots:
    def test_window_outside_working_hours(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T17:00Z", "2025-06-02T23:00Z", 1)
        assert result == []

    def test_no_working_hours_on_requested_day(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-01T00:00Z", "2025-06-01T23:00Z", 1)
        assert result == []

    def test_attendee_busy_entire_window(self):
        alice = {
            "tz": "UTC",
            "hours": {d: ["09:00-17:00"] for d in WEEK},
            "busy": [["2025-06-02T09:00Z", "2025-06-02T17:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 1)
        assert result == []

    def test_no_overlap_between_attendees(self):
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["11:00-12:00"]}}
        result = free_slots([alice, bob], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 1)
        assert result == []


class TestWorkingHoursEdgeCases:
    def test_overnight_working_hours(self):
        alice = {"tz": "UTC", "hours": {"mon": ["22:00-06:00"]}}
        result = free_slots([alice], "2025-06-02T22:00Z", "2025-06-03T06:00Z", 1)
        assert result == [("2025-06-02T22:00:00Z", "2025-06-03T06:00:00Z")]

    def test_overnight_hours_crossing_window(self):
        alice = {"tz": "UTC", "hours": {"mon": ["22:00-06:00"]}}
        result = free_slots([alice], "2025-06-02T23:00Z", "2025-06-03T05:00Z", 1)
        assert result == [("2025-06-02T23:00:00Z", "2025-06-03T05:00:00Z")]

    def test_working_hours_ending_at_24_00(self):
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-24:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-03T00:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-03T00:00:00Z")]

    def test_midnight_to_midnight_as_24_00(self):
        alice = {"tz": "UTC", "hours": {"mon": ["00:00-24:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == [("2025-06-02T00:00:00Z", "2025-06-03T00:00:00Z")]

    def test_multiple_working_hours_same_day(self):
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-12:00", "13:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 1)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T13:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_overlapping_working_hours_same_day(self):
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-13:00", "11:00-15:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T15:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T15:00:00Z")]

    def test_only_some_days_have_working_hours(self):
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"], "fri": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-06T17:00Z", 60)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z"),
        ]

    def test_empty_hours_list_means_no_working_hours(self):
        alice = {"tz": "UTC", "hours": {"mon": [], "tue": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-04T17:00Z", 1)
        # Only Tuesday should have working hours
        assert result == [("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z")]

    def test_missing_weekday_key_means_no_working_hours(self):
        alice = {"tz": "UTC", "hours": {"tue": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-04T17:00Z", 1)
        # Only Tuesday should have working hours (June 3, 2025 is Tuesday)
        assert result == [("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z")]


