        ]


class TestTimezones:
    def test_different_timezones_simple(self):
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        london = {"tz": "Europe/London", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        # NY is UTC-4 in June, London is UTC+1 in June
        # NY 9:00-17:00 = UTC 13:00-21:00
        # London 9:00-17:00 = UTC 8:00-16:00
        # Overlap: UTC 13:00-16:00
        result = free_slots([ny, london], "2025-06-02T13:00Z", "2025-06-02T16:00Z", 1)
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T16:00:00Z")]

    def test_non_overlapping_timezones(self):
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-10:00"] for d in WEEK}}
        tokyo = {"tz": "Asia/Tokyo", "hours": {d: ["09:00-10:00"] for d in WEEK}}
        result = free_slots([ny, tokyo], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == []

    def test_timezone_with_busy_in_different_offset(self):
        tokyo = {
            "tz": "Asia/Tokyo",
            "hours": {d: ["09:00-18:00"] for d in WEEK},
            "busy": [["2025-06-02T12:00:00+09:00", "2025-06-02T13:00:00+09:00"]],
        }
        result = free_slots([tokyo], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        # June 2, 2025 is Monday
        # Tokyo 09:00-18:00 = UTC 00:00-09:00
        # Busy 12:00+09:00 = UTC 03:00
        # Free: UTC 00:00-03:00, 04:00-09:00
        assert result == [
            ("2025-06-02T00:00:00Z", "2025-06-02T03:00:00Z"),
            ("2025-06-02T04:00:00Z", "2025-06-02T09:00:00Z"),
        ]

    def test_multiple_timezones_complex(self):
        sf = {"tz": "America/Los_Angeles", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        chicago = {"tz": "America/Chicago", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        # All in June 2025: SF is UTC-7, Chicago is UTC-5, NY is UTC-4
        # SF 9:00-17:00 = UTC 16:00-00:00
        # Chicago 9:00-17:00 = UTC 14:00-22:00
        # NY 9:00-17:00 = UTC 13:00-21:00
        # Overlap: UTC 16:00-21:00
        result = free_slots([sf, chicago, ny], "2025-06-02T16:00Z", "2025-06-02T21:00Z", 1)
        assert result == [("2025-06-02T16:00:00Z", "2025-06-02T21:00:00Z")]


class TestTimestampFormats:
    def test_timestamp_with_seconds(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots(
            [alice], "2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z", 1
        )
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_timestamp_without_seconds(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_mixed_timestamp_formats(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T09:00:00Z", "2025-06-02T17:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_positive_utc_offset(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots(
            [alice], "2025-06-02T09:00:00+00:00", "2025-06-02T17:00:00+00:00", 1
        )
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_negative_utc_offset(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots(
            [alice], "2025-06-02T09:00:00-00:00", "2025-06-02T17:00:00-00:00", 1
        )
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_various_utc_offsets_equivalent(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        # These all represent the same instant
        result = free_slots([alice], "2025-06-02T13:00:00+04:00", "2025-06-02T17:00:00Z", 1)
        # 13:00+04:00 = 09:00Z
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_fractional_utc_offset(self):
        # Nepal uses +05:45
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots(
            [alice], "2025-06-02T03:15:00+05:45", "2025-06-02T11:15:00+05:45", 1
        )
        # 03:15+05:45 = 21:30 (previous day)Z, 11:15+05:45 = 05:30Z
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T05:30:00Z")] or result == []


class TestMultipleDays:
    def test_free_time_spans_multiple_days(self):
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-04T17:00Z", 60)
        # Mon 09:00-17:00, Tue 09:00-17:00, Wed 09:00-17:00
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
            ("2025-06-04T09:00:00Z", "2025-06-04T17:00:00Z"),
        ]

    def test_free_time_crossing_midnight(self):
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-24:00"], "tue": ["00:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T15:00Z", "2025-06-03T12:00Z", 1)
        # Mon 15:00-00:00 (9 hours) + Tue 00:00-12:00 (12 hours) = continuous 21 hours
        assert result == [("2025-06-02T15:00:00Z", "2025-06-03T12:00:00Z")]

    def test_gaps_in_working_hours_across_days(self):
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"], "fri": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-06T17:00Z", 60)
        # Mon free, Tue-Thu off, Fri free
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z"),
        ]


class TestDSTSpringForward:
    def test_dst_spring_forward_ny_2025(self):
        # On 2025-03-09, US clocks spring forward at 02:00 EST to 03:00 EDT
        # This is at 07:00 UTC
        alice = {
            "tz": "America/New_York",
            "hours": {"sun": ["02:30-04:00"]},
        }
        result = free_slots([alice], "2025-03-09T06:00Z", "2025-03-09T09:00Z", 1)
        # 02:30 EDT is 06:30 UTC, 04:00 EDT is 08:00 UTC
        # But 02:30 EST doesn't exist on this day (clocks skip from 02:00 to 03:00)
        # So "02:30-04:00" covers only 03:00-04:00 EDT = 07:00-08:00 UTC
        assert result == [("2025-03-09T07:00:00Z", "2025-03-09T08:00:00Z")]

    def test_dst_spring_forward_hours_entirely_skipped(self):
        # On 2025-03-09, clocks skip from 02:00 to 03:00 EST->EDT
