    def test_busy_invalid_timestamp_format_error(self):
        """Busy period with invalid timestamp raises ValueError."""
        attendee = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02", "2025-06-02T12:00Z"]],
        }
