            free_slots([attendee], "2025-06-02T00:00Z", "2025-06-02T23:00Z", 60)


class TestResultFormatting:
    """Test result formatting and sorting."""

    def test_result_sorted_by_start_time(self):
        """Results are sorted by start time."""
        attendee = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00Z", "2025-06-02T12:00Z"],
                ["2025-06-02T14:00Z", "2025-06-02T16:00Z"],
            ],
        }
        result = free_slots([attendee], "2025-06-02T00:00Z", "2025-06-02T23:00Z", 30)
        # Verify sorted
        for i in range(len(result) - 1):
            assert result[i][0] < result[i + 1][0]

    def test_result_utc_format(self):
        """Results are in UTC format with Z suffix."""
        attendee = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([attendee], "2025-06-02T09:00Z", "2025-06-02T10:00Z", 30)
        assert len(result) > 0
        for start, end in result:
            assert start.endswith("Z")
            assert end.endswith("Z")
            assert "T" in start
            assert "T" in end

    def test_result_always_has_seconds(self):
        """Result timestamps always include seconds."""
        attendee = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([attendee], "2025-06-02T09:00Z", "2025-06-02T10:00Z", 30)
        assert len(result) > 0
        for start, end in result:
            # Format should be YYYY-MM-DDTHH:MM:SSZ
            assert start.count(":") == 2  # HH:MM:SS
            assert end.count(":") == 2


