    def test_timestamp_with_positive_offset(self):
        """Timestamps with positive UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice],
            "2025-06-02T09:00:00+05:30",
            "2025-06-02T12:00:00+05:30",
            30
        )
        # +05:30 means 09:00+05:30 is 03:30Z, 12:00+05:30 is 06:30Z
        assert result == []

    def test_timestamp_with_negative_offset(self):
        """Timestamps with negative UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice],
            "2025-06-02T13:00:00-04:00",
            "2025-06-02T17:00:00-04:00",
            30
        )
        # -04:00 means 13:00-04:00 is 17:00Z, 17:00-04:00 is 21:00Z
        assert result == []

    def test_timestamp_with_seconds(self):
        """Timestamps including seconds (must be :00)."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice],
            "2025-06-02T09:00:00Z",
            "2025-06-02T12:00:00Z",
            30
        )
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z")]

    def test_busy_timestamp_with_offset(self):
        """Busy period specified with different offset."""
        alice = {
            "tz": "Asia/Tokyo",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00+09:00", "2025-06-02T14:00:00+09:00"]],
        }
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30
        )
        # Tokyo 09:00 = 00:00Z, Tokyo 17:00 = 08:00Z
        # Tokyo 12:00 = 03:00Z, Tokyo 14:00 = 05:00Z
        assert result == [
            ("2025-06-02T00:00:00Z", "2025-06-02T03:00:00Z"),
            ("2025-06-02T05:00:00Z", "2025-06-02T08:00:00Z"),
        ]


