class TestDSTTransitions:
    def test_spring_forward_ny_2025(self):
        """DST spring forward in America/New_York on 2025-03-09."""
        # Clocks jump from 02:00 EST to 03:00 EDT at 07:00Z
        alice = {"tz": "America/New_York", "hours": {"sun": ["02:30-04:00"]}}
        result = free_slots(
            [alice], "2025-03-09T06:00Z", "2025-03-09T10:00Z", 30
        )
        # 02:30 EDT doesn't exist, 03:00-04:00 EDT exists
        # 03:00 EDT = 07:00Z, 04:00 EDT = 08:00Z
        assert result == [("2025-03-09T07:00:00Z", "2025-03-09T08:00:00Z")]

    def test_spring_forward_skipped_time_ny_2025(self):
        """DST spring forward: skipped time slot."""
        # Working hours 02:10-02:50 on 2025-03-09 covers nothing (times are skipped)
        alice = {"tz": "America/New_York", "hours": {"sun": ["02:10-02:50"]}}
        result = free_slots(
            [alice], "2025-03-09T06:00Z", "2025-03-09T10:00Z", 30
        )
        assert result == []

    def test_spring_forward_midnight_spanning_ny_2025(self):
        """DST spring forward: midnight-spanning hours."""
        # 22:00 EST (Saturday) - 02:30 EDT (Sunday, day after clocks jump)
        # Saturday 22:00 EST = 03:00Z, Sunday 02:30 EDT = 07:00Z
        alice = {"tz": "America/New_York", "hours": {"sat": ["22:00-02:30"]}}
        result = free_slots(
            [alice], "2025-03-08T02:00Z", "2025-03-09T10:00Z", 30
        )
        # Saturday 22:00 EST to 03:00 EDT (04:00Z to 07:00Z after adjustment)
        # Actually Sunday 02:30 EDT = Sunday 06:30Z
        # So this spans Saturday 22:00 EST to Sunday 02:30 EDT
        # = 03:00Z (Sat) to 07:00Z (Sun)
        assert result == [("2025-03-08T03:00:00Z", "2025-03-09T07:00:00Z")]

    def test_fall_back_ny_2025(self):
        """DST fall back in America/New_York on 2025-11-02."""
        # Clocks go from 01:59 EDT back to 01:00 EST at 06:00Z
        alice = {"tz": "America/New_York", "hours": {"sun": ["00:00-03:00"]}}
        result = free_slots(
            [alice], "2025-11-02T03:00Z", "2025-11-02T10:00Z", 30
        )
        # 00:00-03:00 appears twice:
        # First: 00:00-01:59 EDT = 04:00-05:59Z
        # Then: 01:00-03:00 EST = 06:00-08:00Z
        # Total = 04:00-08:00Z (four hours, as spec says)
        assert result == [("2025-11-02T04:00:00Z", "2025-11-02T08:00:00Z")]

    def test_fall_back_partial_hour_ny_2025(self):
        """DST fall back: working hour spanning repeated time."""
        # 01:30-09:00 EDT/EST covers repeated 01:00-01:59 hour
        alice = {"tz": "America/New_York", "hours": {"sun": ["01:30-09:00"]}}
        result = free_slots(
            [alice], "2025-11-02T03:00Z", "2025-11-02T14:00Z", 30
        )
        # First 01:30 EDT = 05:30Z, then 09:00 EST = 14:00Z
        # But repeated 01:00-01:59 is covered twice
        # 05:30-06:00Z (first time), 06:00-06:30Z (second time), 06:30-14:00Z (after)
        # Actually merged continuously
        assert result == [("2025-11-02T05:30:00Z", "2025-11-02T14:00:00Z")]


# Multi-day scenarios
class TestMultipleDays:
    def test_two_consecutive_working_days(self):
        """Search window spans two consecutive working days."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 60
        )
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
        ]

    def test_multiple_free_slots_different_days(self):
        """Multiple free slots on different days."""
        alice = {
            "tz": "UTC",
            "hours": {d: ["09:00-12:00", "14:00-17:00"] for d in WEEK},
        }
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 60
        )
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T12:00:00Z"),
            ("2025-06-03T14:00:00Z", "2025-06-03T17:00:00Z"),
        ]

    def test_busy_period_spans_multiple_days(self):
        """Busy period spans multiple days."""
        alice = {
            "tz": "UTC",
            "hours": {d: ["09:00-17:00"] for d in WEEK},
            "busy": [["2025-06-02T12:00Z", "2025-06-04T12:00Z"]],
        }
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-05T00:00Z", 60
        )
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-04T12:00:00Z", "2025-06-04T17:00:00Z"),
        ]


# Error cases
class TestErrorCases:
    def test_error_empty_attendees(self):
        """ValueError when attendees list is empty."""
        with pytest.raises(ValueError):
            free_slots([], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_invalid_timezone(self):
        """ValueError when timezone is not known to zoneinfo."""
        alice = {"tz": "Invalid/Timezone", "hours": {"mon": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_invalid_weekday_key(self):
        """ValueError when hours has invalid weekday key."""
        alice = {"tz": "UTC", "hours": {"monday": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_invalid_hours_format_missing_colon(self):
        """ValueError when hours entry format is invalid (missing colon)."""
        alice = {"tz": "UTC", "hours": {"mon": ["0900-1700"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_invalid_hours_format_wrong_separator(self):
        """ValueError when hours entry uses wrong separator."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00_17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_invalid_hours_format_single_digit(self):
        """ValueError when hours entry has single digits."""
        alice = {"tz": "UTC", "hours": {"mon": ["9:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_invalid_hours_minute_value(self):
        """ValueError when minute value exceeds 59."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:60"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_hours_start_equals_end(self):
        """ValueError when start and end times are equal."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_invalid_end_time_midnight_format(self):
        """ValueError when 24:01 or similar invalid midnight format is used."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-24:01"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 30)

    def test_error_timestamp_no_offset(self):
        """ValueError when timestamp has no UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00", "2025-06-02T12:00Z", 30)

    def test_error_timestamp_nonzero_seconds(self):
        """ValueError when timestamp has non-00 seconds."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00:30Z", "2025-06-02T12:00:00Z", 30)

    def test_error_start_after_end(self):
        """ValueError when start is after end."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T12:00Z", "2025-06-02T09:00Z", 30)

    def test_error_start_equals_end_window(self):
        """ValueError when start equals end."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T10:00Z", "2025-06-02T10:00Z", 30)

    def test_error_busy_start_after_end(self):
        """ValueError when busy pair start is after end."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T14:00Z", "2025-06-02T12:00Z"]],
        }
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T18:00Z", 30)

    def test_error_busy_start_equals_end(self):
        """ValueError when busy pair start equals end."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00Z", "2025-06-02T12:00Z"]],
        }
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T18:00Z", 30)

    def test_error_min_minutes_less_than_one(self):
        """ValueError when min_minutes is less than 1."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", 0)

    def test_error_min_minutes_negative(self):
        """ValueError when min_minutes is negative."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T12:00Z", -1)


# Result format validation
class TestResultFormat:
    def test_result_sorted_by_start(self):
        """Result slots are sorted by start time."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-12:00", "14:00-17:00", "18:00-21:00"]},
        }
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60
        )
        starts = [slot[0] for slot in result]
        assert starts == sorted(starts)

    def test_result_utc_format(self):
        """Result uses UTC format YYYY-MM-DDTHH:MM:SSZ."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60
        )
        for start, end in result:
            assert start.endswith("Z")
            assert end.endswith("Z")
            assert "T" in start
            assert len(start) == 20  # YYYY-MM-DDTHH:MM:SSZ

    def test_result_includes_seconds(self):
        """Result includes seconds in HH:MM:SS format."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60
        )
        for start, end in result:
            parts = start.split(":")
            assert len(parts) == 3
            assert len(parts[2]) == 3  # SSZ


# Edge cases with min_minutes
class TestMinMinutes:
    @pytest.mark.parametrize(
        "minutes,expected",
        [
            (1, 1),  # 1 minute slot
            (30, 1),  # 30 minute slot
            (60, 1),  # 60 minute slot
            (120, 0),  # 120+ minute requirement filters out 60 minute slot
        ],
    )
    def test_min_minutes_boundaries(self, minutes, expected):
        """Test various min_minutes thresholds."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:00"]}}
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", minutes
        )
        assert len(result) == expected


# Complex scenarios
class TestComplexScenarios:
    def test_many_attendees_converging_hours(self):
        """Many attendees with converging working hours."""
        attendees = [
            {"tz": "UTC", "hours": {"mon": [f"{9+i}:00-{18+i}:00"]}}
            for i in range(5)
        ]
        result = free_slots(
            attendees, "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60
        )
        # All must work, so intersection is smallest range
        # Narrowest: 13:00-14:00
        assert len(result) >= 0

    def test_overlapping_midnight_spanning_hours(self):
        """Multiple attendees with midnight-spanning hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["20:00-04:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["22:00-06:00"]}}
        result = free_slots(
            [alice, bob], "2025-06-02T00:00Z", "2025-06-03T12:00Z", 60
        )
        # Overlap: 22:00 (Mon) to 04:00 (Tue)
        assert result == [("2025-06-02T22:00:00Z", "2025-06-03T04:00:00Z")]

    def test_different_tz_with_midnight_hours(self):
        """Different timezones with midnight-spanning hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["22:00-06:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["23:00-05:00"]}}
        result = free_slots(
            [alice, bob], "2025-06-02T00:00Z", "2025-06-03T12:00Z", 60
        )
        # Overlap: 23:00 (Mon) to 05:00 (Tue)
        assert result == [("2025-06-02T23:00:00Z", "2025-06-03T05:00:00Z")]
